inline_styles:
/* Renewal Detail Page Styling */
.skpd-hero {
  background: linear-gradient(135deg, #07192f 0%, #0d2b52 60%, #0f1a30 100%);
  color: #fff;
  padding: 48px 0 42px;
  border-bottom: 4px solid #E8611A;
}
.skpd-breadcrumbs {
  font-size: 13px;
  color: #94a3b8;
  margin-bottom: 16px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.skpd-breadcrumbs a {
  color: #cbd5e1;
  text-decoration: none;
}
.skpd-breadcrumbs a:hover {
  color: #fdba74;
}
.skpd-hero h1 {
  font-size: clamp(24px, 3.4vw, 38px);
  font-weight: 800;
  line-height: 1.3;
  margin-bottom: 14px;
  color: #ffffff;
}
.skpd-hero p.lead {
  font-size: clamp(15px, 1.8vw, 17px);
  color: #cbd5e1;
  max-width: 800px;
  line-height: 1.6;
  margin-bottom: 24px;
}
.skpd-quick-specs {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.12);
  font-size: 13.5px;
}
.skpd-spec-item {
  background: rgba(255,255,255,0.06);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 8px;
  padding: 10px 16px;
}
.skpd-spec-item strong {
  color: #fdba74;
}

/* Content Layout */
.skpd-body-grid {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 36px;
  padding: 48px 0 60px;
}
@media (max-width: 900px) {
  .skpd-body-grid {
    grid-template-columns: 1fr;
  }
}
.skpd-content h2 {
  font-size: 23px;
  color: #0f172a;
  font-weight: 800;
  margin: 36px 0 16px;
  border-bottom: 2px solid #f1f5f9;
  padding-bottom: 10px;
}
.skpd-content h2:first-of-type {
  margin-top: 0;
}
.skpd-content h3 {
  font-size: 18.5px;
  color: #1e293b;
  font-weight: 700;
  margin: 24px 0 12px;
}
.skpd-content p, .skpd-content li {
  font-size: 15px;
  color: #334155;
  line-height: 1.7;
}
.skpd-step-list {
  padding-left: 20px;
  margin: 16px 0 24px;
}
.skpd-step-list li {
  margin-bottom: 12px;
}
.skpd-callout-info {
  background: #f0fdf4;
  border-left: 4px solid #16a34a;
  padding: 16px 20px;
  border-radius: 0 10px 10px 0;
  margin: 24px 0;
  font-size: 14.5px;
  color: #14532d;
}
.skpd-callout-info strong {
  display: block;
  font-size: 15px;
  margin-bottom: 6px;
  color: #0f5132;
}

/* Sidebar Box */
.skpd-sidebar-card {
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 24px;
  position: sticky;
  top: 90px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.04);
}
.skpd-sidebar-card h3 {
  font-size: 18px;
  color: #0f172a;
  font-weight: 800;
  margin: 0 0 14px;
}
.skpd-price-display {
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  padding: 16px;
  margin-bottom: 20px;
}
.skpd-price-display .price-val {
  font-size: 24px;
  font-weight: 800;
  color: #0A4A2E;
  margin: 4px 0 2px;
}
.skpd-sidebar-list {
  list-style: none;
  padding: 0;
  margin: 16px 0 24px;
  font-size: 13.5px;
}
.skpd-sidebar-list li {
  padding: 8px 0;
  border-bottom: 1px solid #f1f5f9;
  display: flex;
  align-items: center;
  gap: 8px;
  color: #475569;
}
.skpd-sidebar-list li svg {
  width: 16px;
  height: 16px;
  color: #16a34a;
  flex-shrink: 0;
}
.skpd-btn-wa-full {
  display: block;
  text-align: center;
  background: #25D366;
  color: #fff;
  font-weight: 700;
  font-size: 15px;
  padding: 13px 20px;
  border-radius: 10px;
  text-decoration: none;
  transition: background .2s ease;
}
.skpd-btn-wa-full:hover {
  background: #20ba5a;
  color: #fff;
}
